 </table>

 <h2>3. Business Rules</h2>
 <table>
 <thead><tr><th>#</th><th>Name</th><th>Table</th><th>When</th><th>Order</th><th>Logic</th></tr></thead>
 <tbody>
 <tr><td>1</td><td>Date Validation</td><td>u_project</td><td>before insert/update</td><td>100</td><td>Abort if end_date &lt; start_date</td></tr>
 <tr><td>2</td><td>Completion Validation</td><td>u_project</td><td>before insert/update</td><td>200</td><td>Abort if % not 0-100</td></tr>
 <tr><td>3</td><td>Auto Closure</td><td>u_project</td><td>before update</td><td>300</td><td>100% → completed + inactive</td></tr>
 <tr><td>4</td><td>Health Calculation</td><td>u_project</td><td>before insert/update</td><td>400</td><td>Green/Amber/Red based on timeline</td></tr>
 <tr><td>5</td><td>Task Rollup</td><td>u_project_task</td><td>after insert/update/delete</td><td>100</td><td>AVG(task%) → project%</td></tr>
 <tr><td>6</td><td>Task Completion Validation</td><td>u_project_task</td><td>before insert/update</td><td>100</td><td>Abort if % not 0-100</td></tr>
