 <tbody>
 <tr><td><code>draft</code></td><td>Draft</td><td>Initial creation, not yet approved</td></tr>
 <tr><td><code>planned</code></td><td>Planned</td><td>Approved and scheduled</td></tr>
 <tr><td><code>in_progress</code></td><td>In Progress</td><td>Active work underway</td></tr>
 <tr><td><code>on_hold</code></td><td>On Hold</td><td>Temporarily paused</td></tr>
 <tr><td><code>completed</code></td><td>Completed</td><td>All work finished</td></tr>
