",":root {
 --docs-bg: rgb(var(--now-color--neutral-0, 255, 255, 255));
 --docs-text: rgb(var(--now-color--neutral-18, 22, 27, 33));
 --docs-text-secondary: rgb(var(--now-color--neutral-12, 99, 114, 131));
 --docs-border: rgb(var(--now-color--neutral-5, 218, 222, 227));
 --docs-header-bg: rgb(var(--now-color--primary-1, 227, 246, 253));
 --docs-accent: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --docs-tab-hover: rgb(var(--now-color--neutral-2, 243, 244, 246));
 --docs-code-bg: rgb(var(--now-color--neutral-2, 243, 244, 246));
 --docs-table-header: rgb(var(--now-color--neutral-3, 233, 235, 238));
 --docs-table-stripe: rgb(var(--now-color--neutral-1, 249, 249, 250));
 --docs-success: rgb(var(--now-color--positive-2, 208, 244, 220));
 --docs-warning: rgb(var(--now-color--warning-2, 255, 240, 204));
 --docs-danger: rgb(var(--now-color--critical-2, 255, 224, 224));
}

* {
 margin: 0;
 padding: 0;
 box-sizing: border-box;
}

body {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 background-color: var(--docs-bg);
 color: var(--docs-text);
 line-height: 1.6;
}

.docs-container {
 max-width: 1200px;
 margin: 0 auto;
 padding: 0 24px;
}

.docs-header {
 padding: 32px 0 24px;
 border-bottom: 2px solid var(--docs-accent);
 margin-bottom: 0;
}

.docs-title {
 font-size: 28px;
 font-weight: 600;
 color: var(--docs-text);
 margin: 0;
}

.docs-subtitle {
 font-size: 16px;
 color: var(--docs-text-secondary);
 margin-top: 4px;
}

.docs-nav {
 display: flex;
 flex-wrap: wrap;
 gap: 0;
 border-bottom: 1px solid var(--docs-border);
 padding: 0;
 margin-bottom: 32px;
 position: sticky;
 top: 0;
 background: var(--docs-bg);
 z-index: 10;
}

.docs-tab {
 padding: 12px 20px;
 border: none;
 background: transparent;
 font-size: 14px;
 font-weight: 500;
 color: var(--docs-text-secondary);
 cursor: pointer;
 border-bottom: 3px solid transparent;
 transition: all 0.2s ease;
 font-family: inherit;
}

.docs-tab:hover {
 background: var(--docs-tab-hover);
 color: var(--docs-text);
}

.docs-tab--active {
 color: var(--docs-accent);
 border-bottom-color: var(--docs-accent);
 font-weight: 600;
}

.docs-content {
 padding-bottom: 64px;
}

/* Documentation Content Styles */
.doc-section {
 animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
 from { opacity: 0; transform: translateY(4px); }
 to { opacity: 1; transform: translateY(0); }
}

.doc-section h1 {
 font-size: 24px;
 font-weight: 600;
 margin: 0 0 8px;
 color: var(--docs-text);
}

.doc-section h2 {
 font-size: 20px;
 font-weight: 600;
 margin: 32px 0 16px;
 padding-bottom: 8px;
 border-bottom: 1px solid var(--docs-border);
 color: var(--docs-text);
}

.doc-section h3 {
 font-size: 16px;
 font-weight: 600;
 margin: 24px 0 12px;
 color: var(--docs-text);
}

.doc-section p {
 margin: 0 0 12px;
 color: var(--docs-text);
}

.doc-section ul, .doc-section ol {
 margin: 0 0 16px;
 padding-left: 24px;
}

.doc-section li {
 margin-bottom: 6px;
}

.doc-section table {
 width: 100%;
 border-collapse: collapse;
 margin: 16px 0;
 font-size: 14px;
}

.doc-section th {
 background: var(--docs-table-header);
 padding: 10px 12px;
 text-align: left;
 font-weight: 600;
 border: 1px solid var(--docs-border);
}

.doc-section td {
 padding: 8px 12px;
 border: 1px solid var(--docs-border);
}

.doc-section tr:nth-child(even) td {
 background: var(--docs-table-stripe);
}

.doc-section code {
 background: var(--docs-code-bg);
 padding: 2px 6px;
 border-radius: 3px;
 font-size: 13px;
 font-family: "SFMono-Regular", "Menlo", monospace;
}

.doc-section pre {
 background: var(--docs-code-bg);
 padding: 16px;
 border-radius: 6px;
 overflow-x: auto;
 margin: 16px 0;
 border: 1px solid var(--docs-border);
}

.doc-section pre code {
 background: none;
 padding: 0;
 font-size: 13px;
 line-height: 1.5;
}

.doc-section .info-box {
 padding: 12px 16px;
 border-radius: 6px;
 margin: 16px 0;
 border-left: 4px solid;
}

.doc-section .info-box--tip {
 background: var(--docs-success);
 border-left-color: rgb(var(--now-color--positive-3, 52, 168, 83));
}

.doc-section .info-box--warning {
 background: var(--docs-warning);
 border-left-color: rgb(var(--now-color--warning-3, 234, 134, 0));
}

.doc-section .info-box--danger {
 background: var(--docs-danger);
 border-left-color: rgb(var(--now-color--critical-3, 211, 47, 47));
}

/* Diagram Styles */
.diagram-container {
 background: var(--docs-bg);
 border: 1px solid var(--docs-border);
 border-radius: 8px;
 padding: 24px;
 margin: 16px 0;
 overflow-x: auto;
}

.diagram-box {
 display: inline-block;
 padding: 10px 16px;
 border-radius: 6px;
 margin: 4px;
 font-size: 13px;
 font-weight: 500;
}

.diagram-box--primary {
 background: rgb(var(--now-color--primary-2, 186, 230, 245));
 border: 1px solid var(--docs-accent);
 color: var(--docs-text);
}

.diagram-box--secondary {
 background: var(--docs-table-header);
 border: 1px solid var(--docs-border);
}

.diagram-arrow {
 display: inline-block;
 padding: 0 8px;
 color: var(--docs-text-secondary);
 font-size: 18px;
}

.diagram-section {
 margin: 24px 0;
 padding: 20px;
 border: 1px solid var(--docs-border);
 border-radius: 8px;
}

.diagram-section-title {
 font-size: 14px;
 font-weight: 600;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 color: var(--docs-text-secondary);
 margin-bottom: 12px;
}

.diagram-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
 gap: 12px;
}

.diagram-card {
 padding: 12px 16px;
 border-radius: 6px;
 background: var(--docs-tab-hover);
 border: 1px solid var(--docs-border);
}

.diagram-card-title {
 font-weight: 600;
 font-size: 14px;
 margin-bottom: 4px;
}

.diagram-card-desc {
 font-size: 12px;
 color: var(--docs-text-secondary);
}

.relationship-line {
 display: flex;
 align-items: center;
 padding: 8px 0;
 gap: 12px;
}

.relationship-table {
 padding: 6px 12px;
 background: rgb(var(--now-color--primary-2, 186, 230, 245));
 border: 1px solid var(--docs-accent);
 border-radius: 4px;
 font-weight: 500;
 font-size: 13px;
}

.relationship-type {
 font-size: 12px;
 color: var(--docs-text-secondary);
 font-style: italic;
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useCallback, useEffect } from "react";
import "./styles.css";
import TechnicalDoc from "./components/TechnicalDoc";
import FunctionalDoc from "./components/FunctionalDoc";
import AdminGuide from "./components/AdminGuide";
import UserGuide from "./components/UserGuide";
import ArchitectureDiagram from "./components/ArchitectureDiagram";
import TableRelationshipDiagram from "./components/TableRelationshipDiagram";

const TABS = [
 { id: "technical", label: "Technical Documentation" },
 { id: "functional", label: "Functional Documentation" },
 { id: "admin", label: "Admin Guide" },
 { id: "user", label: "User Guide" },
 { id: "architecture", label: "Architecture Diagram" },
 { id: "relationships", label: "Table Relationships" }
];

function getTabFromUrl(): string {
 const params = new URLSearchParams(window.location.search);
 return params.get("tab") || "technical";
}

export default function App() {
 const [activeTab, setActiveTab] = useState<string>(getTabFromUrl);

 useEffect(() => {
 const onPopState = () => setActiveTab(getTabFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigateToTab = useCallback((tabId: string) => {
 const params = new URLSearchParams({ tab: tabId });
 const relativePath = `${window.location.pathname}?${params}`;
 const tabLabel = TABS.find(t => t.id === tabId)?.label || "Documentation";
 const pageTitle = `Project Docs - ${tabLabel}`;

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath,
 title: pageTitle
 });
 }
 window.history.pushState({ tab: tabId }, "", relativePath);
 document.title = pageTitle;
 setActiveTab(tabId);
 }, []);

 const renderContent = () => {
 switch (activeTab) {
 case "technical": return <TechnicalDoc />;
 case "functional": return <FunctionalDoc />;
 case "admin": return <AdminGuide />;
 case "user": return <UserGuide />;
 case "architecture": return <ArchitectureDiagram />;
 case "relationships": return <TableRelationshipDiagram />;
 default: return <TechnicalDoc />;
 }
 };

 return (
 <div className="docs-container">
 <header className="docs-header">
 <h1 className="docs-title">Project Governance & Assignment Management</h1>
 <p className="docs-subtitle">Application Documentation</p>
 </header>
 <nav className="docs-nav">
 {TABS.map(tab => (
 <button
 key={tab.id}
 className={`docs-tab ${activeTab === tab.id ? "docs-tab--active" : ""}`}
 onClick={() => navigateToTab(tab.id)}
 >
 {tab.label}
 </button>
 ))}
 </nav>
 <main className="docs-content">
 {renderContent()}
 </main>
 </div>
 );
}
